#include <iostream>
#include <vector>
using namespace std;

int main() {
    int N;
    long long S;

    while (cin >> N >> S) {
        vector<long long> arr(N);
        long long sum = 0;
        int maxIndex = 0;

        for (int i = 0; i < N; ++i) {
            cin >> arr[i];
            sum += arr[i];

            if (arr[i] > arr[maxIndex])
                maxIndex = i;
        }

        if (N > 0) {
            sum -= arr[maxIndex];
            arr[maxIndex] = 0;
        }

        for (int i = 0; i < N; ++i)
            cout << arr[i] << (i + 1 == N ? '\n' : ' ');

        cout << (sum <= S ? "YES" : "NO") << '\n';
    }

    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int N;
    long long S;

    while (cin >> N >> S) {
        long long sum = 0, maximum = 0;

        for (int i = 0; i < N; ++i) {
            long long value;
            cin >> value;
            sum += value;
            maximum = max(maximum, value);
        }

        cout << (sum - maximum <= S ? "YES" : "NO") << '\n';
    }

    return 0;
}

